/** Softmax numerators e_j for distances D (decreasing table), per layer. */
export type ExpVec<L extends number, D> = L extends 0
  ? { [J in keyof D]: L0_exp_m<D[J] & string> }
  : L extends 1
  ? { [J in keyof D]: L1_exp_m<D[J] & string> }
  : L extends 2
  ? { [J in keyof D]: L2_exp_m<D[J] & string> }
  : L extends 3
  ? { [J in keyof D]: L3_exp_m<D[J] & string> }
  : never;
/** Probabilities p_j for distances D shifted by the log-sum-exp Lse, per layer. */
export type ProbVec<L extends number, D, Lse extends string> = L extends 0
  ? { [J in keyof D]: L0_prob_m<`${D[J] & string}${Lse}`> }
  : L extends 1
  ? { [J in keyof D]: L1_prob_m<`${D[J] & string}${Lse}`> }
  : L extends 2
  ? { [J in keyof D]: L2_prob_m<`${D[J] & string}${Lse}`> }
  : L extends 3
  ? { [J in keyof D]: L3_prob_m<`${D[J] & string}${Lse}`> }
  : never;

